static int failures = 0;
#define CHECK(cond, ...) do { if (!(cond)) { failures++; printf("FAIL: " __VA_ARGS__); printf("\n"); } } while (0)

int main() {
  // 1. Real captured frames decode to the expected bytes.
  for (auto &s : SAMPLES) {
    Frame f;
    DecodeResult r = decode(s.raw, f);
    CHECK(r == OK, "real frame %s: %s", s.expect, result_str(r));
    if (r == OK) CHECK(f.hex() == s.expect, "real frame decoded as %s, expected %s", f.hex().c_str(), s.expect);
  }

  for (auto &s : LATE_EDGE_SAMPLES) {
    Frame f;
    DecodeResult r = decode(s.raw, f);
    CHECK(r == OK, "late-edge frame %s: %s", s.expect, result_str(r));
    if (r == OK) CHECK(f.hex() == s.expect, "late-edge frame decoded as %s, expected %s", f.hex().c_str(), s.expect);
  }

  // 2. The master frames we transmit are bit-exact copies of the remote's.
  struct { uint8_t fl, reg, hi, lo; const char *expect; } m[] = {
      {0x00, 0x1A, 0, 0, "80 1A 00 00"},    {0x10, 0x38, 0xAA, 120, "10 38 AA 78"},
      {0x00, 0xD3, 0, 0, "80 D3 00 00"},    {0x00, 0x96, 0, 0, "00 96 00 00"},
      {0x10, 0xC8, 0xE0, 0, "90 C8 E0 00"}, {0x10, 0xC8, 0xC0, 0, "10 C8 C0 00"},
      {0x10, 0xC8, 0x40, 0, "90 C8 40 00"}, {0x00, 0x00, 0, 0, "00 00 00 00"}};
  for (auto &x : m) {
    Frame f = make_master(x.fl, x.reg, x.hi, x.lo);
    CHECK(f.hex() == x.expect, "make_master gave %s, expected %s", f.hex().c_str(), x.expect);
  }

  // 3. Encode -> decode round trip for many frames, with every edge moved by up to +-100 us
  //    (more than the ~60 us seen on the real bus). Pulse lengths then vary by up to +-200 us.
  srand(1);
  for (int i = 0; i < 20000; i++) {
    Frame f = make_master(rand() & 0x7F, rand() & 0xFF, rand() & 0xFF, rand() & 0xFF);
    auto raw = encode(f);
    int32_t prev_j = 0;
    for (size_t k = 0; k < raw.size(); k++) {
      int32_t j = (k + 1 < raw.size()) ? (rand() % 201) - 100 : 0;  // jitter of the edge ending this pulse
      int32_t a = std::abs(raw[k]) + j - prev_j;
      raw[k] = raw[k] > 0 ? a : -a;
      prev_j = j;
    }
    raw.push_back(-10000);  // trailing idle as the receiver reports it
    Frame g;
    DecodeResult r = decode(raw, g);
    CHECK(r == OK && g.hex() == f.hex(), "round trip %s -> %s (%s)", f.hex().c_str(), g.hex().c_str(), result_str(r));
    if (failures > 10) break;
  }

  // 3b. Burner-time heater frames: one edge up to 200 us late or early (204 us is the most
  //     seen), every edge moved by up to +-10 us (the heater's measured jitter is about +-5 us),
  //     and a sender clock up to 1% fast or slow.
  for (int i = 0; i < 20000; i++) {
    Frame f = make_master(rand() & 0x7F, rand() & 0xFF, rand() & 0xFF, rand() & 0xFF);
    auto raw = encode(f);
    double clock = 1.0 + ((rand() % 201) - 100) / 10000.0;
    size_t late = rand() % (raw.size() - 1);
    int32_t shift = (rand() % 401) - 200;
    int32_t prev_j = 0;
    for (size_t k = 0; k < raw.size(); k++) {
      int32_t j = (k + 1 < raw.size()) ? (rand() % 21) - 10 + (k == late ? shift : 0) : 0;
      int32_t a = (int32_t) (std::abs(raw[k]) * clock) + j - prev_j;
      raw[k] = raw[k] > 0 ? a : -a;
      prev_j = j;
    }
    raw.push_back(-10000);
    Frame g;
    DecodeResult r = decode(raw, g);
    CHECK(r == OK && g.hex() == f.hex(), "late edge %s -> %s (%s)", f.hex().c_str(), g.hex().c_str(), result_str(r));
    if (failures > 10) break;
  }

  // 4. Corrupted frames are rejected.
  Frame f = make_master(0x10, 0x38, 0xAA, 120), g;
  auto raw = encode(f);
  auto truncated = std::vector<int32_t>(raw.begin(), raw.end() - 6);
  CHECK(decode(truncated, g) != OK, "truncated frame accepted");
  auto badtime = raw; badtime[5] = badtime[5] > 0 ? 760 : -760;
  CHECK(decode(badtime, g) != OK, "1.5 half-bit pulse accepted");
  Frame bad = f; bad.b[3] ^= 0x01;   // one data bit flipped, parity now wrong
  CHECK(decode(encode(bad), g) == BAD_PARITY, "parity error not detected");

  printf("%s (%zu real frames, %zu late-edge frames, 2 x 20000 round trips)\n", failures ? "FAILED" : "all tests passed",
         SAMPLES.size(), LATE_EDGE_SAMPLES.size());
  return failures ? 1 : 0;
}
